import{_ as r,a as d,b as i}from"./chunks/remote-storage.Cdpka9Ya.js";import{_ as l,C as s,o as n,c,a2 as o,j as g,a as e,E as h}from"./chunks/framework.Dx-TCpNt.js";const q=JSON.parse('{"title":"リモート保存とバックアップ","description":"画像は別のディスク、NAS 共有、WebDAV サーバーに置いたまま、注釈はローカルの data/ フォルダに保存できます。このページでは、リモートライブラリの動作、ネットワークがすねたときの挙動、バックアップの仕組みを説明します。","frontmatter":{"description":"画像は別のディスク、NAS 共有、WebDAV サーバーに置いたまま、注釈はローカルの data/ フォルダに保存できます。このページでは、リモートライブラリの動作、ネットワークがすねたときの挙動、バックアップの仕組みを説明します。"},"headers":[],"relativePath":"ja/guide/remote.md","filePath":"ja/guide/remote.md","lastUpdated":1794848531000}'),p={name:"ja/guide/remote.md"};function b(u,t,m,_,f,A){const a=s("Badge");return n(),c("div",null,[t[2]||(t[2]=o('<h1 id="リモート保存とバックアップ" tabindex="-1">リモート保存とバックアップ <a class="header-anchor" href="#リモート保存とバックアップ" aria-label="Permalink to &quot;リモート保存とバックアップ&quot;">​</a></h1><p>画像は別のディスク、NAS 共有、WebDAV サーバーに置いたまま、注釈はローカルの <code>data/</code> フォルダに保存できます。このページでは、リモートライブラリの動作、ネットワークがすねたときの挙動、バックアップの仕組みを説明します。</p><h2 id="解決する課題" tabindex="-1">解決する課題 <a class="header-anchor" href="#解決する課題" aria-label="Permalink to &quot;解決する課題&quot;">​</a></h2><p>漫画ライブラリは、アプリにインデックスさせたいディスクよりはるかに大きいことが多く、すでに NAS にあることもあります。数万枚の画像を <code>raw/</code> にコピーするのは無駄です。その一方で、注釈は小さく、Wi-Fi がまばたきしただけで失われてはいけません。</p><p>KomaYomi はこの2つを分けます。<strong>画像は必要に応じてリモートから読み、注釈はローカルに書きます。</strong></p><h2 id="リモートライブラリの設定" tabindex="-1">リモートライブラリの設定 <a class="header-anchor" href="#リモートライブラリの設定" aria-label="Permalink to &quot;リモートライブラリの設定&quot;">​</a></h2><ol><li>サイドバーの <strong>バックアップ / 復元</strong> を開きます。</li><li><strong>リモート素材 / ネットワークストレージ</strong> で <strong>リモートフォルダを追加</strong> をクリックします。</li><li>対象を入力します。</li></ol><table tabindex="0"><thead><tr><th>フィールド</th><th>意味</th></tr></thead><tbody><tr><td><strong>名前</strong></td><td>ダイアログに表示されるラベル。</td></tr><tr><td><strong>種類</strong></td><td>ローカルフォルダ、ネットワークドライブ / UNC、WebDAV。</td></tr><tr><td><strong>フォルダパス</strong></td><td>例：<code>D:\\manga</code> または <code>\\\\nas\\share\\manga</code>（ローカル / ネットワーク）。</td></tr><tr><td><strong>WebDAV アドレス</strong>、<strong>ユーザー名</strong>、<strong>パスワード</strong></td><td>WebDAV の認証情報。</td></tr><tr><td><strong>読み取り専用</strong></td><td>アプリが書き込まないよう、ソースを読み取り専用にします。</td></tr></tbody></table><ol start="4"><li><strong>接続をテスト</strong> をクリックします。ダイアログに <em>オンライン</em> / <em>オフライン</em> と、対象が読み取り専用かどうかが表示されます。</li><li><strong>リモートのフォルダツリーを同期</strong> をクリックします。</li></ol><h3 id="同期の動作" tabindex="-1">同期の動作 <a class="header-anchor" href="#同期の動作" aria-label="Permalink to &quot;同期の動作&quot;">​</a></h3><p>アプリはリモートフォルダを走査し、ローカルのミラー（<code>data/cache/remote/tree/</code>）に <strong>0 バイトのプレースホルダーファイル</strong> を作成します。通常のライブラリスキャナーとフォルダ規則がそのミラーに対して実行されるため、リモートの巻はローカルと同じように、同じ 巻 → 言語 → 話 のグループ化でサイドバーに表示されます。</p><ul><li>ミラーされるのは画像の拡張子だけです：<code>.jpg</code>、<code>.jpeg</code>、<code>.png</code>、<code>.webp</code>、<code>.gif</code>、<code>.avif</code>、<code>.bmp</code>。</li><li>走査は深さ10階層、<strong>20,000 ファイル</strong> までです。上限に達すると「ファイル上限に達しました」と報告して停止します。</li><li>読み取れないフォルダはカウントして報告され、同期は中断されません。</li><li>再度同期するとミラーは置き換わります。注釈は影響を受けません。</li></ul><h2 id="オンデマンドの読み込みとキャッシュ" tabindex="-1">オンデマンドの読み込みとキャッシュ <a class="header-anchor" href="#オンデマンドの読み込みとキャッシュ" aria-label="Permalink to &quot;オンデマンドの読み込みとキャッシュ&quot;">​</a></h2><p>ページを開くと、次の順に処理されます。</p><ol><li>アプリはローカルキャッシュに元ファイルがあるか確認します。</li><li>ない場合、リモートソースからファイルを取得します。</li><li>バイト列はプロバイダーとパスごとに、内容に基づいて識別され、<code>data/cache/remote/files/</code> に書き込まれます。</li><li>サムネイルはキャッシュされた元ファイルから生成されます。</li></ol><p>「ライブラリ全体をダウンロードする」手順はありません。実際に開いたページだけが取得されます。</p><table tabindex="0"><thead><tr><th>コントロール</th><th>意味</th></tr></thead><tbody><tr><td><strong>キャッシュ n MB / 上限 MB（m ファイル）</strong></td><td>現在のキャッシュ使用量。</td></tr><tr><td><strong>キャッシュ上限（MB）</strong></td><td>上限。既定は <strong>512 MB</strong> で、100,000 までの正の値を指定できます。</td></tr><tr><td><strong>画像キャッシュを消去</strong></td><td>キャッシュされたリモートの元ファイルとサムネイルを削除します。安全に使え、再取得されます。</td></tr></tbody></table><p>キャッシュが上限を超えると、最も長く使われていないファイルから削除され、使用量が上限の <strong>90%</strong> を下回るまで続きます。</p><h2 id="オフライン時の動作" tabindex="-1">オフライン時の動作 <a class="header-anchor" href="#オフライン時の動作" aria-label="Permalink to &quot;オフライン時の動作&quot;">​</a></h2><p>ネットワークは失われる前提です。</p><table tabindex="0"><thead><tr><th>状況</th><th>結果</th></tr></thead><tbody><tr><td>キャッシュ済みのページ</td><td>オフラインでも通常どおり開きます。</td></tr><tr><td>未キャッシュのページ、リモートがオフライン</td><td>画像リクエストは HTTP <strong>503</strong> <code>ERR_REMOTE_UNAVAILABLE</code> で失敗し、UI は待ち続けずにエラーを表示します。</td></tr><tr><td>未キャッシュのページのサムネイル、リモートがオフライン</td><td>HTTP <strong>502</strong> <code>ERR_THUMB_FETCH_FAILED</code>。</td></tr><tr><td>注釈、ノート、コマ</td><td>常にローカルです。画像がキャッシュ済みのページは編集を続けられます。</td></tr></tbody></table><p>保存に失敗したとき——ブラウザがオフライン、サーバーが再起動中、5xx が返った——ページ文書は失われません。ブラウザのストレージにあるローカルの <strong>アウトボックス</strong>（書き込み待ちキュー）に入り、後で再送されます。</p><ul><li>1ページにつき1件。同じページの新しい書き込みは古いものを置き換えるため、再送は何度繰り返しても安全です。</li><li>上限は 100 ページ。ブラウザのストレージが一杯になると、まず貼り付けたスクリーンショットを捨てて、ノート本文を残します。</li><li>再送は、読み込み時、ブラウザがオンラインに戻ったとき、未送信が残っている間は30秒ごと、そして保留件数のチップから手動で実行できます。</li><li>最初の失敗で止めて、版履歴の順序を保ち、後で再試行します。</li></ul><p>これはブラウザ側のバッファであり、リモート同期ではありません。書き込み先は常にローカルの <code>data/</code> フォルダです。</p><div class="tip custom-block"><p class="custom-block-title">実用的なオフライン利用</p><p>オフラインになる前に、学習する予定のページを開いておいてください。元ファイルとサムネイルがキャッシュされるため、そのまま読めます。持ち運べる量はキャッシュ上限で決まります。</p></div><h2 id="パスワードと認証情報" tabindex="-1">パスワードと認証情報 <a class="header-anchor" href="#パスワードと認証情報" aria-label="Permalink to &quot;パスワードと認証情報&quot;">​</a></h2><ul><li>パスワードは <code>storage.json</code> に<strong>保存されません</strong>。</li><li><strong>AES-256-GCM</strong> で <code>data/secrets.json.enc</code> に暗号化され、インストールごとの鍵ファイル <code>data/.secret.key</code>（モード <code>0600</code> で作成）を使います。</li><li>そのため、<code>data/</code> フォルダをコピーしたり同期したりしてもパスワードは漏れません。UI がパスワードを表示し直すこともないので、保存済みの値を保つにはパスワード欄を空欄にしてください。</li><li>パスワードは<strong>バックアップから除外されます</strong>。</li></ul><h2 id="バックアップ先" tabindex="-1">バックアップ先 <a class="header-anchor" href="#バックアップ先" aria-label="Permalink to &quot;バックアップ先&quot;">​</a></h2><p>同じダイアログに <strong>バックアップ先</strong> が一覧表示されます。バックアップ先は、バックアップ ZIP のアップロード先です。</p><ol><li><strong>バックアップ先を追加</strong> で、ローカルフォルダ、ネットワークドライブ、WebDAV を選びます。</li><li><strong>この保存先へバックアップ</strong> は <code>data/</code> の ZIP を作成し、そのバックアップ先の <code>backups/backup-&lt;timestamp&gt;.zip</code> にアップロードします。</li><li>完了すると、対象、ファイル名、サイズが表示されます。</li></ol><p>設定済みのソースとバックアップ先は <strong>接続をテスト</strong> で確認でき、オフラインのものは報告されます。</p><figure class="shot"><img src="'+r+'" alt="バックアップ / 復元ダイアログのバックアップ先。NAS のアドレス、バックアップ実行と編集のボタン、バックアップ先の追加"><figcaption>バックアップ先。各項目に名前とアドレスが表示されます。この保存先へバックアップ は `data/` を ZIP にして保存先の `backups/` へ送り、バックアップ先を追加 ではローカルフォルダ、ネットワークドライブ、WebDAV を選べます。</figcaption></figure><h2 id="手動のバックアップと復元" tabindex="-1">手動のバックアップと復元 <a class="header-anchor" href="#手動のバックアップと復元" aria-label="Permalink to &quot;手動のバックアップと復元&quot;">​</a></h2><figure class="shot"><img src="'+d+'" alt="バックアップと復元のダイアログ。バックアップの生成、ファイルの選択、検査後の内容要約"><figcaption>バックアップダイアログ。復元の前にアーカイブを検査するので、上書きする前にページ数、ノート数、テンプレート数を確認できます。</figcaption></figure><ul><li><strong>バックアップを生成してダウンロード</strong> は <code>data/</code> の ZIP を作成します。ページ、テンプレート、プリセット、レイアウト、<code>library.json</code>、<code>.backup-meta.json</code> を含みます。サムネイルキャッシュと一時ファイルは除外されます。</li><li><strong>バックアップファイルを選択…</strong> はまず ZIP を検査し、含まれるページ、ノート、テンプレート、プリセットの数と、対象の巻を報告します。</li><li>復元は <code>data/</code> の同名ファイルを<strong>上書き</strong>しますが、バックアップにないページは削除しません。復元の前に現在のデータのスナップショットが書き出されます。</li></ul><p>ファイル単位の契約とストレージ JSON の正確な内容は、<a href="/KomaYomi-docs/ja/remote-backup">リモート保存とバックアップ（リファレンス）</a> を参照してください。</p><h2 id="現在の制限" tabindex="-1">現在の制限 <a class="header-anchor" href="#現在の制限" aria-label="Permalink to &quot;現在の制限&quot;">​</a></h2>',37)),g("p",null,[t[0]||(t[0]=e("以下は ",-1)),h(a,{type:"warning",text:"予定"}),t[1]||(t[1]=e(" のままです。",-1))]),t[3]||(t[3]=o('<ul><li>WebDAV 以外のクラウドプロバイダー（Dropbox / Google Drive / S3 との連携はありません）。</li><li>定期バックアップのリモート先への自動アップロード：<strong>定期バックアップ</strong> はローカルの <code>exports/</code> に <code>auto-backup-*.zip</code> を書き出すだけで、リモート先への移動は手動です。</li></ul><figure class="shot"><img src="'+i+'" alt="バックアップ / 復元のリモートストレージ。WebDAV の取得元、キャッシュ使用量、バックアップ先"><figcaption>「バックアップ / 復元」のリモートストレージ。WebDAV の取得元、キャッシュ使用量、バックアップ先。</figcaption></figure><h2 id="よくある落とし穴" tabindex="-1">よくある落とし穴 <a class="header-anchor" href="#よくある落とし穴" aria-label="Permalink to &quot;よくある落とし穴&quot;">​</a></h2><ul><li><strong>リモートの巻が表示されない。</strong> <strong>リモートのフォルダツリーを同期</strong> を実行してください。ライブラリがスキャンするのはミラーです。結果のファイル上限とスキップされたフォルダ数を確認してください。</li><li><strong>すべてのページが 503 になる。</strong> リモートがオフラインで、そのページが一度もキャッシュされていません。再接続してからページを開き直してください。</li><li><strong>ディスク使用量が増え続ける。</strong> キャッシュ上限は既定で 512 MB です。意図して引き上げるか、ライブラリを切り替えるときにキャッシュを消去してください。</li><li><strong>バックアップにパスワードがない。</strong> 仕様です。別のマシンで復元した後にパスワードを再入力してください。</li><li><strong>ネットワークパスはエクスプローラーでは使えるのに、ここでは使えない。</strong> ネットワークドライブは、アプリを実行するアカウントから到達できる必要があります。サービスや別のデスクトップユーザーで動かす場合に問題になります。</li></ul><h2 id="関連項目" tabindex="-1">関連項目 <a class="header-anchor" href="#関連項目" aria-label="Permalink to &quot;関連項目&quot;">​</a></h2><ul><li><a href="/KomaYomi-docs/ja/remote-backup">バックアップのリファレンス</a> — ストレージ JSON とファイル単位の詳細。</li><li><a href="/KomaYomi-docs/ja/guide/gallery">ライブラリとインポート</a> — フォルダ規則はミラーにも適用されます。</li><li><a href="/KomaYomi-docs/server/error-codes">サーバーと CLI のメッセージコード</a> — <code>ERR_REMOTE_UNAVAILABLE</code>、<code>ERR_THUMB_FETCH_FAILED</code>。</li></ul>',6))])}const x=l(p,[["render",b]]);export{q as __pageData,x as default};
